   "kurz": "Meist ist nicht der Pieks das Schlimme, sondern die Angst davor, und Hinauszögern verlängert sie nur. Hilfreich sind eine ehrliche Ankündigung des Termins, Rollenspiele zum Üben und für wichtige Medizin ein Plan A, B und C. Festhalten beim Impfen gilt als legitim, wenn euch die Impfung wichtig ist; das sind Erfahrungen, kein ärztlicher Rat.",
