     "text": "Die Hosts gehen davon aus, dass Impfen sinnvoll ist, und nehmen das als Prämisse. Sie halten Festhalten für Eltern, denen die Impfung wichtig ist, für legitim und ohne schlechtes Gewissen vertretbar, lehnen es aber ab, es als Tabu darzustellen. Bei Kindern, die darauf mit Panik reagieren, ist Festhalten für sie keine Option. Unsicherheit der Eltern übertrage sich auf das Kind. Eine Ärztin sollte nach ihrer Ansicht sicher auftreten und das Kind nicht entscheiden lassen, ob geimpft wird; einmal um einen kurzen Moment zu bitten sei okay, wiederholtes Zögern halte nur auf. Eine Host würde eher auf Vorbereitung und rechtzeitiges Ankündigen setzen und findet Bestechung mit Süßem eine schlechte Wahl. Bei Medizin nimmt ein Host auch Belohnungen als Plan B für legitim. Bleibt ein Kind nach dem Termin zwei Stunden oder länger aufgelöst oder hat panische Angst, raten sie, Unterstützung bei Fachleuten zu suchen. Angst entstehe oft schon durch eine einzelne unangenehme Erfahrung und mache Eltern nicht zu schlechten Eltern."
