   "kurz": "Kinder lernen Aufräumen und Mithelfen, wenn Aufgaben für sie sichtbar sind und sie früh mitmachen dürfen. Die Hosts von mutti setzen auf Starthilfe, Spiel und ruhiges Dranbleiben; Nicola Schmidt betont dagegen, dass Hausarbeit ein gemeinsames Tun als Familie ist, bei dem das Kind mitentscheidet. Beide wollen keinen Kampf und keine Belohnung als Hebel.",
