   "kurz": "Es ist normal, dass ein Baby nur mit Körperkontakt schläft, die meisten tun das, und ihr habt nichts falsch gemacht. Die mutti-Hosts finden Federwiege und andere Schlafhilfen unproblematisch, solange sie der Familie nutzen. Nicola Schmidt lehnt Schreienlassen klar ab, hält Schlafregressionen zu festen Zeitpunkten für einen Mythos und empfiehlt einen gleichbleibenden Ablauf vor dem Schlafen.",
