   "kurz": "Die mutti-Hosts erziehen nicht mehr bedürfnisorientiert und erleben diesen Ansatz vor allem als erschöpfend und in der Praxis oft zu permissiv. Nicola Schmidt hält dagegen am bindungs- und bedürfnisorientierten Ansatz fest, betont aber, dass Bedürfnisse anerkennen nicht heißt, sie immer zu erfüllen, und dass Eltern Orientierung geben müssen. Beide fragen also nach Führung, bewerten die Methode selbst aber sehr unterschiedlich.",
