     "podcast": "artgerecht",
     "text": "Nicola Schmidt sieht Bedürfnisorientierung als Kern ihres Ansatzes und grenzt sich zugleich vom reinen Nachgeben ab. Bedürfnisse anzuerkennen heiße nicht, sie immer zu erfüllen: Eltern dürfen Nein sagen, ohne das Kind zu beschämen. Laut ihr entwickeln Kinder, deren Bedürfnisse mitfühlend beantwortet werden, mehr Selbstkontrolle. Kleinkinder können die Folgen ihrer spontanen Wünsche nicht absehen, deshalb müssten Eltern als Menschen mit Erfahrung Orientierung geben. Mit den mutti-Hosts trifft sie sich in der Forderung nach Führung und in der Unterscheidung von Wunsch und Bedürfnis. Sie widerspricht ihnen aber darin, dass der Ansatz selbst das Problem sei: Für sie ist feinfühliges Reagieren gerade der Weg, nicht permissive Erziehung."
