   "kurz": "Belohnungssysteme sind laut den Hosts von mutti nicht pauschal schlecht. Sie helfen vor allem dabei, Gewohnheiten aufzubauen oder festgefahrene Muster zu durchbrechen, sollten aber nicht für Dinge eingesetzt werden, die das Kind ohnehin gern macht. Nicola Schmidt lehnt Belohnungen dagegen fürs Mithelfen im Haushalt ab, weil dort die Zugehörigkeit zählt.",
