    "Setzt sehr kleine, sicher erreichbare Ziele, etwa eine Autofahrt von 20 Minuten ohne Ärger statt eines ganzen Nachmittags, und prüft, ob euer Kind die Voraussetzungen hat, das Ziel überhaupt zu erreichen.",
