     "podcast": "artgerecht",
     "text": "Nicola Schmidt weist die Schuldzuweisung ans Stillen zurück und sagt, Ähnliches höre man auch bei der Kita-Eingewöhnung. Bindung sei wie Surfen oder Fahrradfahren: Wer es auf einem Rad gelernt hat, kann es auch auf einem anderen, braucht vielleicht etwas Übung. Wer die Bindung bei seiner wichtigsten Bezugsperson gut lernt, könne sich auch an andere binden. Dabei sei egal, ob das Mama, Papa, Oma oder eine Pflegefamilie ist. Kleinkinder könnten sich laut den Aussagen in der Folge an etwa vier bis fünf Bezugspersonen fest binden. Viele, aber nicht alle Kinder fremdelten ab etwa acht bis neun Monaten, unterschiedlich stark. Die Gründe seien nicht geklärt, dazu gebe es keine Forschung. Eine Vermutung sei, dass Säuglinge in diesem Alter besonders verletzlich für eine Trennung von ihrer Bindungsperson sind."
