   "kurz": "Einen biologischen Mutterinstinkt gibt es nach dieser Sicht nicht. Beim Menschen existiert höchstens ein schwacher Brutpflegeinstinkt, etwa Babygesichter süß zu finden, und fast alles andere ist erlernt. Dass Frauen sich oft leichter tun, lässt sich auf Erziehung und Erfahrung zurückführen.",
