     "text": "Die Hosts sehen Großeltern als Privileg und wertvolle Ressource und warnen davor, sie wegen kleiner Differenzen wegzustoßen. Ihrer Erfahrung nach lagen Großeltern mit Ratschlägen häufig richtig, haben Praxiserfahrung, wiederholen eigene Fehler meist nicht und sind weniger gestresst. Wer Ratschläge ablehnt, werde von Großeltern oft als zurückgewiesen erlebt, was die Fronten verhärten kann. Kinder lernen laut ihnen von mehreren Bezugspersonen mit verschiedenen Rollen, und Großeltern gleichen oft den Stil der Eltern aus. Für die Entwicklung reicht eine sichere Bindung, eine weniger sichere zu den Großeltern ist nicht dramatisch. Die Hosts räumen ein, dass es bei stark gewaltvollen Erziehungsvorstellungen oder fehlender Beziehung anders aussieht, und betonen, dass Eltern ohne unterstützende Großeltern trotzdem gut genug sind. Wenn Eltern von den eigenen Eltern nie ernst genommen wurden, kann das viele Trigger auslösen. Eine Hostin würde Kinder auch mit etwas Traurigkeit bei den Großeltern lassen, wenn sie dort gut aufgehoben sind, die andere teilt das nicht in jeder Härte. Beim Thema Grenzen sind sie sich nicht ganz einig, wie dogmatisch man sein muss."
