   "kurz": "Kinder wollen grundsätzlich gern kooperieren, doch Stress, Hunger, Müdigkeit, Impulse oder ein Gehirn, das Anweisungen noch nicht leicht umsetzen kann, stehen dem oft im Weg. Hosts und Nicola Schmidt (artgerecht) raten übereinstimmend zu klaren, positiven Ansagen, weniger Reden und Kontakt vor Anweisung; Nicola Schmidt ergänzt, dass viele Neins Kinder dichtmachen lassen und dass bei Schulkindern Verhandeln statt Druck hilft.",
   "tipps": [
    "Beruhigt ein Kind im Stressmodus oder im Wutanfall zuerst, denn erst danach kann es wieder zuhören und mitmachen.",
    "Geht zum Kind hin, holt es auf Augenhöhe ab und sagt klar, was ihr wollt, statt im Vorbeigehen oder aus einem anderen Raum zu rufen; sagt, was das Kind tun soll, nicht was es lassen soll, zum Beispiel leise rennen wie ein Ninja.",
    "Sagt in einfachen Ich-Sätzen, was ihr wollt, und macht aus einer Erwartung keine Frage oder Bitte, denn ein Nein ist dann eine echte Option; laut Nicola Schmidt hilft es, mit der Stimme unten zu bleiben.",
    "Folgt dem Kind zuerst in sein Spiel oder bei seinem Anliegen (zum Beispiel beim Suchen der Schlafmaske) und führt es danach in Mini-Schritten dorthin, wo ihr hinwollt.",
    "Redet weniger und handelt mehr: einmal sagen, euch selbst fertig machen, zur Tür gehen und dem Kind Zeit geben, ohne ihm hinterherzulaufen. Zwingt es nicht körperlich mitzukommen.",
    "Gebt dem Impuls des Kindes ein Ja und bietet eine Alternative zum Verbotenen an, etwa Hörbuch, Lego oder Bewegung draußen; achtet auf die Zahl der Neins und Korrekturen am Tag und lasst Unwichtiges weg.",
    "Achtet auf ausgeschlafene, satte Kinder, plant morgens 10 bis 20 Minuten freies Spiel ein und bereitet Übergänge vor.",
    "Macht Alltagsaufgaben zum Spiel, etwa kurz Fangen mit dem Schuh oder Verbotsspiele beim Händewaschen, und leitet kleine Kinder beim Anziehen ohne Worte an.",
    "Bei Schulkindern: Hört zuerst zu, fragt nach der Sicht des Kindes, legt vorher fest, welche Grenzen nicht verhandelbar sind, und sucht für den Rest gemeinsam eine Lösung, auch die zweitbeste."
   ],
   "sichtweisen": [
    {
     "podcast": "mutti",
     "text": "Die Hosts unterscheiden mit Verweis auf Jesper Juul zwischen Gehorsam und Kooperation. Gehorsam entsteht ihrer Darstellung nach durch Druck, Angst oder Manipulation und beruht auf Hierarchie, Kooperation ist freiwillig und beruht auf Beziehung. Hinter scheinbarem Trotz kann sich nach Juul auch verdeckte Kooperation verbergen, wenn das Kind eine unausgesprochene Erwartung der Eltern spürt und erfüllt. Zur Erklärung ziehen sie die Gehirnentwicklung heran: Eine Anweisung zu befolgen verlangt Verstehen, Impulskontrolle und Planung, und der dafür zuständige präfrontale Kortex ist bei Kindern laut den Hosts noch unreif und unter Stress gehemmt. Eine Hostin hält es für zu dogmatisch, hinter jedem Verhalten ein Bedürfnis zu suchen, manchmal sei es einfach Interaktion. In der Folge zum Nichthören sind sich die Hosts einig, dass ein Vater in einem Hörerbeispiel zu viel erwartet; sie sind aber uneins, ob Hunger oder schlichtes Nichtmitbekommen der Hauptgrund war. Sie lehnen körperliches Durchsetzen und Drohen ab und betonen, dass ein Kind, das nicht mitmacht, nicht heißt, dass Eltern versagt haben."
    },
    {
     "podcast": "artgerecht",
     "text": "Nicola Schmidt fragt zuerst nach dem Alter, weil die Gründe fürs Nichthören stark variieren: Kleine Kinder werden von Impulsen überrollt, Grundschulkinder und Teenager machen laut ihr bei sehr vielen Neins dicht und schalten auf Durchzug. Wie die Hosts rät sie zu klaren Ich-Botschaften und zu Ansagen statt Fragen, und auch sie betont, dass es keine Garantie gibt. Ihr Leitprinzip \"Folgen vor Führen\" geht über die mutti-Tipps hinaus: Erst Kontakt herstellen und dem Kind folgen, dann führen. Anders als die Hosts argumentiert sie stark mit Sprachforschung (nach ihrer Aussage sind negative Formulierungen schwerer zu verarbeiten) und mit der Zahl der Neins. Bei Schulkindern setzt sie ausdrücklich auf Verhandeln und Kooperation statt Druck, mit wenigen festen Grenzen bei Schlaf und Sicherheit."
    }
   ],
