    "Schaut, was euer Kind braucht: Kinder, die Zeit zum Ankommen brauchen, profitieren davon, dass ihr jeden Schritt erklärt; andere brauchen einen klaren Anfang, ein kurzes Ritual und ein klares Signal, ohne dass ihr zurückkommt.",
