   "kurz": "Beide Eltern hatten vor dem ersten Kind kaum realistische Vorstellungen und erlebten die Babyzeit härter, als sie erwartet hatten. Werdende Eltern sollten deshalb von großen Veränderungen ausgehen, statt auf den besten Fall zu hoffen. Wer mit viel Wandel rechnet, wird eher positiv überrascht.",
