    "Diskutiert nicht jedes Mal neu: Wer anfängt zu diskutieren, bekommt eine Diskussion. Erklärt eure Gründe lieber in einem ruhigen Moment, etwa beim Spazierengehen.",
    "Kommuniziert klar, statt überzeugen zu wollen; seid ihr selbst sicher, was das Beste ist, hört das Diskutieren meist bald auf.",
