    "Prüft bei anhaltendem Widerstand, ob die Regel zum Kind passt: Ist sie zu schwer oder steckt ein echtes Problem dahinter, etwa zu kleine Kleidung? Begleitet das Kind dann vorübergehend und führt es danach wieder an die Regel heran.",
    "Traut dem Kind zu, was es kann, und erledigt es nicht doch selbst, mit Verweis auf Selbstwirksamkeit.",
    "Formuliert statt eines Verbots einen Wunsch und bleibt dabei, auch wenn es heute nicht klappt; setzt Regeln nicht mit Gewalt durch, etwa durch Wegreißen von Spielzeug.",
    "Fragt euch, welches Bedürfnis hinter dem Verhalten steckt, und bietet eine Alternative an, etwa eine Kiste Sand für ein Kind, das Blumentöpfe ausgräbt, oder Wasserspiel in der Wanne statt Wasser auf dem Tisch.",
    "Spürt ihr, dass ihr hart oder verkrampft werdet, haltet kurz inne und prüft, ob es nur um Macht geht, und nehmt euch Zeit für eine passende Reaktion statt Strafen."
