     "podcast": "artgerecht",
     "text": "Nicola Schmidt stimmt den Hosts zu, dass man bei einer Regel bleibt und konsequent sein soll, auch weil gemischte Botschaften der Eltern Kinder verwirren; auch sie sagt, dass man nicht gewinnen muss. Sie wird bei den Mitteln deutlicher als die Hosts: Gewalt ist für sie nur zur Gefahrenabwehr oder beim Stoppen von Hauen angebracht, Beschämung und moralischer Druck bringen laut ihr nichts. Ergänzend rät sie, hinter dem Verhalten das Bedürfnis zu suchen, eine Alternative anzubieten und freundlich, mit klaren Wünschen oder Ich-Botschaften statt vielen Neins zu sprechen. Sie beruft sich auf die Forschung, nennt aber keine einzelne Studie. Sie gibt zu, früher selbst von der Sorge getrieben gewesen zu sein, das Kind lerne es sonst nie."
