     "text": "Nicola Schmidt beschreibt zwei Stressreaktionen: Manche Eltern werden körperlich fahrig und wollen Probleme durch Machen lösen, andere erstarren und sind innerlich trotzdem unruhig. Innen laufe oft ein Alarmmodus mit rasenden Gedanken, flacher oder angehaltener Atmung und dem Gefühl, die Gefahr sofort abwenden zu müssen. Wenn Eltern sagen, alles sei gut, innerlich aber angespannt sind, passen Worte und Zustand nicht zusammen. Sie räumt ein, früher genervt auf Atemtipps reagiert zu haben, ist inzwischen aber überzeugt, dass sie wirken. Mit tief durchatmen meint sie vor allem langes Ausatmen."
