   "bereiche": [
    "grenzen",
    "alltag"
   ],
   "kurz": "Eine Konsequenz hängt inhaltlich mit dem Verhalten zusammen und kommt ohne Rache aus; was keinen Bezug hat, ist eher eine Strafe. Die Hosts von mutti halten Konsequenzen für einen legitimen Teil von Erziehung, sparsam und ruhig eingesetzt, Nicola Schmidt hält Strafen für wenig sinnvoll und setzt auf frühe Grenzen. Beide achten auf den direkten Bezug zum Verhalten.",
   "tipps": [
    "Fragt euch, ob die Folge zum Verhalten passt, denn wer mit Essen wirft, bekommt danach kein Eis, während kein Eis wegen nicht aufgeräumter Sachen eine Strafe ohne Zusammenhang wäre.",
    "Setzt Grenzen früh, bevor etwas eskaliert, damit dem Kind eine unangenehme Folge erspart bleibt und ihr nicht reflexhaft zur Strafe greift.",
    "Entscheidet nicht im Zorn, denn Wut führt schnell in den Strafmodus und ihr überlegt besser später in Ruhe, was angemessen ist.",
    "Zieht die Folge direkt und sofort, etwa indem ihr nach der Pfütze gleich nach Hause geht und das Kind umzieht; lange Strafen wie eine Woche Hausarrest kann ein Kind zeitlich nicht überblicken.",
    "Probiert vor einer Konsequenz andere Wege: ein Spiel, Gegenständen eine Stimme geben, gemeinsam anpacken oder nonverbale Hinweise.",
    "Kündigt nur an, was ihr sofort umsetzen und wirklich durchziehen wollt, und nennt bei kleinen Kindern die Folge vorher, während ihr sie bei älteren, die die Regel kennen, direkt umsetzen könnt.",
    "Macht ein Kind etwas aus Versehen kaputt, braucht es keine Maßnahme, ihr wischt gemeinsam auf und stellt Gläser sicherer hin oder nehmt zeitweise Becher.",
    "Statt Süßes zu verbieten, vertröstet verbindlich („Nach dem Frühstück gibt es Gummibärchen“) und haltet das Versprechen.",
    "Rechnet damit, dass es viele Wiederholungen und Jahre brauchen kann, bis eine Konsequenz beim Kind ankommt."
   ],
   "sichtweisen": [
    {
     "podcast": "mutti",
     "text": "Die Hosts grenzen sich von der bedürfnisorientierten Szene ab, in der ihrer Meinung nach jedes „Wenn, dann“ als schlecht gilt. Das finden sie zu schwarz-weiß. Natürliche Konsequenzen allein sind für sie oft ein Alibi, um sich als gute Eltern zu fühlen, denn gerade bei sozialem Verhalten kommen die Folgen zu spät. Die Unterscheidung zwischen natürlichen und logischen Konsequenzen halten sie für wenig hilfreich. Entscheidend sind für sie Haltung und Verhältnismäßigkeit: Wer will, dass das Kind leidet, bestraft, und Drohungen wie kein Weihnachtsgeschenk bei nicht aufgegessenem Essen sind klar unverhältnismäßig. Eine Host will Drohen und Konsequenzen-Ankündigen klar trennen, die andere hält das teils für Wortklauberei. Beide räumen ein, dass ihnen selbst Drohungen herausrutschen. In einer Folge berufen sie sich außerdem auf eine Studie, nach der Schimpfen das Verhalten nur kurz stoppt und langfristig mit mehr Aggression und Ängsten verbunden ist, ein ruhiges Time-out aber wirke. Ein Kind festzuhalten, um Ruhe zu erzwingen, lehnen sie als Gewalt ab. Auch eine kaputte Sache muss für sie nicht jedes Mal eine Konsequenz haben. Bei einer verweigerten Sonnencreme setzen sie auf lange Kleidung und Hut, ohne das als Folge zu benennen."
    },
    {
     "podcast": "artgerecht",
     "text": "Nicola Schmidt unterscheidet zwei Dinge: Eine Strafe hat keinen Bezug zu dem, was das Kind getan hat, eine Konsequenz schon, und eine Konsequenz folgt zeitlich sofort. Laut ihr weiß ein Kind nach drei Tagen Hausarrest nur noch, dass es Hausarrest hat, aber nicht mehr, warum, und auch nach der stillen Treppe erinnern sich kleine Kinder kaum an das Geschehene. Natur eignet sich für Konsequenzen, weil sie klar ist, komplexe Folgen wie eine Erkältung Tage später kann ein kleines Kind aber nicht verknüpfen. Strafen, Konsequenzen und Grenzen sind für sie drei getrennte Themen, und Grenzen dürfen weiter gesetzt werden. Mit mutti stimmt sie im Bezug zum Verhalten überein; sie ist aber deutlich skeptischer gegenüber Strafen und nimmt sich selbst nicht aus, wenn sie müde ist und eine Eskalation übersieht."
    }
   ],
