   "kurz": "Ein Kind ist kein unbeschriebenes Blatt, denn Verhalten entsteht aus Temperament, Übung und Erziehung zusammen. Deshalb lässt sich von außen kaum beurteilen, ob eine andere Familie etwas richtig oder falsch macht. Gleichzeitig zeigen sich bei einem selbst klare Wirkungen von Erziehung.",
