   "kurz": "Die verbreitete Annahme, dass Wut auf das Kind meist auf ein Kindheitstrauma zurückgeht, halten die Autoren für falsch. Elterliche Wut ist häufig eine gelernte Bewertung der Situation, und hilfreicher als die Ursachensuche in der Vergangenheit ist, die Bewertung zu ändern und Verantwortung zu übernehmen. Echte Traumata nehmen sie ausdrücklich ernst. Das ist ihre Sicht und keine therapeutische Empfehlung.",
