    "Nach einem Meltdown geht auf Schadensbegrenzung: Reize runter, Ruhe, Schlaf oder ruhiges Spiel statt Ausflug. Holt Kinder möglichst rein, bevor sie kippen, und prüft, was nach der Kita hilft, etwa rausgehen, im Auto kuscheln oder Aktivitäten aufs Wochenende zu legen.",
    "Bei einem Streit wie dem um die Socken: Lasst das Kind selbst holen, macht ein Spiel daraus (etwa ein Sockenmonster) oder erledigt es gemeinsam. Wiederholt sich ein Streitpunkt, ändert den Ablauf, zum Beispiel Socken vorab aussuchen lassen.",
    "Kommt es jeden Abend zum Ausbruch, prüft Schlafenszeit und Tagesbelastung. Setzt bei häufigen Ausbrüchen eher beim Schlaf, bei Reizen und Essen an als bei der Grenze.",
