     "text": "Die Hosts sind klar gegen gewaltsames Zähneputzen und gegen Drohungen, zeigen aber Verständnis für Eltern, die aus Verzweiflung so reagieren. Zwang führt laut ihnen eher zu Vermeidung und kann auch Angst vor dem Zahnarzt fördern. In einer Folge schlagen sie eine Reihenfolge vor: erst auffordern, dann nonverbale Hinweise, Spiele, Video, Belohnung, Konsequenz und ganz zuletzt Festhalten. Eine Konsequenz wie „morgen nichts Süßes“ finden sie besser als Festhalten, in der späteren Folge halten sie Festhalten nur in Ausnahmen wie Medikamenten für vertretbar. Die Hosts nehmen Zähne ernst, ordnen aber ein, dass ein Tag ohne Putzen nicht gleich Löcher bedeutet, solange nicht ständig Zucker oder Saft dazukommt. Karies hängt laut ihnen auch von der Veranlagung ab, man könne nicht auf schlechte Eltern schließen. Den Begriff Belohnungssystem empfinden sie als Reizwort und sprechen lieber von Gewohnheits-Tracking. Sie geben teils Aussagen ihrer Zahnärztinnen wieder und sagen selbst, dass sie sich damit weniger gut auskennen. Eine Host denkt sich viele Spiele für den Alltag aus, die andere nutzt Fertigmach-Situationen eher als Beziehungszeit."
